import logging
import uuid

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self._stock = stock

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self._stock.reserve(item, quantity)
        except Exception:
            reference = uuid.uuid4().hex[:12]
            logger.error(
                "Unexpected error while reserving item=%r quantity=%r for user=%r (reference=%s)",
                item, quantity, user, reference, exc_info=True,
            )
            if is_admin:
                text = (
                    f"An unexpected error occurred (reference: {reference}). "
                    f"Please check the server logs for details."
                )
            else:
                text = (
                    f"Sorry, something went wrong while processing your order "
                    f"(reference: {reference}). Please try again later."
                )
            return 500, text

        return 200, (
            f"Thank you, {user}! Your order for {quantity} x {item} "
            f"has been reserved (reservation #{reservation_id})."
        )
